package com.example.bandlink.service; import com.example.bandlink.entity.*; import com.example.bandlink.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.time.LocalDateTime;
@Service public class PostImageService{private final PostRepository posts;private final PostImageRepository images;private final UserRepository users;private final ImageStorageService storage;public PostImageService(PostRepository p,PostImageRepository i,UserRepository u,ImageStorageService s){posts=p;images=i;users=u;storage=s;}@Transactional public String add(Long uid,Long pid,MultipartFile file){Post p=posts.findByIdAndUserId(pid,uid).orElseThrow();if(p.getStatus()!=PostStatus.OPEN)throw new IllegalArgumentException("公開中の投稿のみ画像を変更できます");if(images.countByPostId(pid)>=5)throw new IllegalArgumentException("画像は5枚までです");String url=storage.store(file);images.save(new PostImage(p,url,(int)images.countByPostId(pid),LocalDateTime.now()));return url;}}
